// Image decode probes using the repo-owned 16x16 quadrant images generated by
// scripts/generate-images.py. Each image is decoded, drawn to a canvas and
// sampled at the four quadrant centres; lossy AVIF gets a small tolerance.
import { round } from './fonts';

export interface ImageResult {
  format: string;
  src: string;
  decoded: boolean;
  naturalSize: string | null;
  decodeMs: number | null;
  pixelsMatch: boolean | null;
  samples: number[][] | null;
  error?: string;
}

export interface ImageReport {
  results: ImageResult[];
  pictureAvifSelected: string | null;
  createImageBitmap: boolean;
  canvasEncode: Record<string, boolean>;
}

/** Expected RGBA at (4,4) (12,4) (4,12) (12,12); keep in sync with the generator. */
export const QUADRANTS: [number, number, number[]][] = [
  [4, 4, [255, 0, 0, 255]],
  [12, 4, [0, 255, 0, 255]],
  [4, 12, [255, 255, 255, 255]],
  [12, 12, [0, 0, 255, 128]],
];

const FORMATS: [string, string, number][] = [
  ['png', 'img/probe.png', 0],
  ['svg', 'img/probe.svg', 2],
  ['webp (lossless)', 'img/probe.webp', 0],
  ['avif', 'img/probe.avif', 6],
];

async function probe(format: string, src: string, tolerance: number): Promise<ImageResult> {
  const img = new Image();
  const start = performance.now();
  img.src = src;
  try {
    await img.decode();
  } catch (err) {
    return { format, src, decoded: false, naturalSize: null, decodeMs: null, pixelsMatch: null, samples: null, error: String(err) };
  }
  const decodeMs = round(performance.now() - start);
  const canvas = document.createElement('canvas');
  canvas.width = 16;
  canvas.height = 16;
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  if (!ctx) return { format, src, decoded: true, naturalSize: `${img.naturalWidth}x${img.naturalHeight}`, decodeMs, pixelsMatch: null, samples: null, error: 'no 2d canvas' };
  ctx.drawImage(img, 0, 0, 16, 16);
  const samples = QUADRANTS.map(([x, y]) => Array.from(ctx.getImageData(x, y, 1, 1).data));
  const pixelsMatch = QUADRANTS.every(([, , want], i) => want.every((c, k) => Math.abs(c - samples[i][k]) <= tolerance));
  return { format, src, decoded: true, naturalSize: `${img.naturalWidth}x${img.naturalHeight}`, decodeMs, pixelsMatch, samples };
}

export async function runImageProbes(picture: HTMLImageElement | null): Promise<ImageReport> {
  const results: ImageResult[] = [];
  for (const [format, src, tol] of FORMATS) results.push(await probe(format, src, tol));
  const canvas = document.createElement('canvas');
  canvas.width = 2;
  canvas.height = 2;
  const canvasEncode: Record<string, boolean> = {};
  for (const type of ['image/png', 'image/webp', 'image/avif', 'image/jpeg']) {
    canvasEncode[type] = canvas.toDataURL(type).startsWith(`data:${type}`);
  }
  if (picture && !picture.complete) await picture.decode().catch(() => undefined);
  return {
    results,
    pictureAvifSelected: picture ? picture.currentSrc.split('/').pop() ?? null : null,
    createImageBitmap: typeof createImageBitmap === 'function',
    canvasEncode,
  };
}
